import numpy as np
from rcb_client import Robot
r=Robot();s=r.spec();R=np.array(s['action_types']['joint_position']['range_rad'],float);base=np.array([.0046,.0009,-.7,.9,-.2,.0071,-.0093,-.7,.9,-.2,.0008,-.004,-.0015,-.0094,-.0075,.0034,.0029,.0023,-.0023]);
while True:
 st=r.status();n=min(100,1000-st['control_steps']);
 if st['done'] or not n:print('END',st);break
 A=[];start=st['control_steps']
 for k in range(n):
  t=(start-100+k+1)*.02;sn=np.sin(2*np.pi*2*t);q=base.copy();q[2]+=.25*sn;q[7]-=.25*sn;ll=.24*max(0,-sn);lr=.24*max(0,sn);q[3]+=ll;q[8]+=lr;q[4]-=.25*sn+ll;q[9]+=.25*sn-lr;q[11]-=.1*sn;q[15]+=.1*sn;A.append(np.clip(2*(q-R[:,0])/(R[:,1]-R[:,0])-1,-1,1))
 o=r.submit('joint_position',np.array(A),interpolate='linear',cameras=[],video='none');p=o.meta['proprio']['now'];print(o.meta['control_steps'],o.meta['done'],o.meta['reason'],np.round(p[41:44],2),np.round(p[38:41],2))
 if o.done:break
